const x = (a: number[]): string[] => a.map((i) => HEX[i]);

export const PALETTES: AdminPalette[] = PACKED.map((p) => ({
  id: p[0], name: p[1], note: p[2], bucket: p[3], level: p[4],
  accent: x(p[5]), accentDark: x(p[6]), tier: x(p[7]), tierDark: x(p[8]),
  series: x(p[9]), seriesDark: x(p[10]), cvd: p[11], nv: p[12],
}));

/** Skupine boja za filtar u galeriji (id -> hrvatska oznaka). */
export const PALETTE_BUCKETS: Array<[string, string]> = [
  ['sve', 'Sve'], ['ljubicasta', 'Ljubičasta'], ['plava', 'Plava'], ['tirkiz', 'Tirkiz'],
  ['zelena', 'Zelena'], ['narancasta', 'Narančasta'], ['roza', 'Roza'], ['crvena', 'Crvena'],
];

/** Razine tamnoce za filtar (id -> oznaka). */
export const PALETTE_LEVELS: Array<[string, string]> = [
  ['sve', 'Sve tamnoće'], ['0', 'Najtamnije'], ['1', 'Vrlo tamno'], ['2', 'Tamno'], ['3', 'Srednje'],
];

export const DEFAULT_PALETTE_ID = "violet-cyan-0";

export function paletteById(id: string): AdminPalette | undefined {
  return PALETTES.find((p) => p.id === id);
}
